SET NAMES utf8mb4;

INSERT INTO `products` (`id`, `user_id`, `slug`, `title`, `description`, `install_guide`, `price`, `sale_price`, `type`, `status`, `featured`, `version`,
  `video_url`, `features`, `compatibility`, `screenshots`, `pack_meta`, `created_at`, `published_at`) VALUES
('p0000000-0000-0000-0000-000000569253', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'yakuza-pvp-fivem-server', 'Yakuza PVP — FiveM PVP Server', '<p><b>Yakuza Empire RP</b> is a premium FiveM PVP roleplay server built with custom scripts, a unique map and optimized performance — ready for you to launch as your own server.</p><p>Watch the official trailer above to see the gameplay, the city and the systems in action.</p>', '<ol><li>Download the server files from <b>My library</b>.</li><li>Import the included SQL file into your MySQL/MariaDB database.</li><li>Put your database connection and licence key in <code>server.cfg</code>.</li><li>Start the server with txAdmin and log in.</li></ol><p>Need help? Open a support ticket from your account and we will help you get it running.</p>', 199.00, '125.00', 'server_pack', 'PUBLISHED', 1, '1.0.0', 'https://youtu.be/xdjtK4X06GE', '["Complete PVP roleplay server, ready to launch", "Custom PVP scripts and balanced gameplay", "Unique map and custom vehicles", "Gangs and community-driven systems", "Discord server layout with role hierarchy and welcome messages", "Optimized for smooth performance"]', '["QBCore"]', '["images/products/yakuza-pvp-fivem-server-1.webp", "images/products/yakuza-pvp-fivem-server-2.webp", "images/products/yakuza-pvp-fivem-server-3.webp", "images/products/yakuza-pvp-fivem-server-4.webp"]', '{"resources": 0, "resmon_idle_ms": "", "frameworks": ["QBCore"], "features": ["Complete PVP roleplay server, ready to launch", "Custom PVP scripts and balanced gameplay", "Unique map and custom vehicles", "Gangs and community-driven systems", "Discord server layout with role hierarchy and welcome messages", "Optimized for smooth performance"], "lifetime_updates": true}', '2026-08-24 21:15:58', '2026-08-24 21:15:58'),
('p0000000-0000-0000-0000-000000512709', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'fivem-ultimate-advanced-rp-server', 'FiveM Ultimate Advanced RP Server – Full Premium Build', '<p>Launch a professional FiveM roleplay server today. This is a complete, fully configured and optimized server — not a basic base — with advanced systems, custom jobs, player-owned businesses, gangs, heists and a modern UI.</p><h3>What you receive</h3><ul><li>Full ready server files</li><li>Fully configured scripts</li><li>Optimized performance</li><li>Easy installation</li><li>Full showcase video (above)</li></ul><h3>Perfect for</h3><ul><li>Starting a professional FiveM RP server</li><li>New RP communities</li><li>Developers who want an advanced base instead of months of building</li></ul>', '<ol><li>Download the server files from <b>My library</b>.</li><li>Import the included SQL file into your MySQL/MariaDB database.</li><li>Put your database connection and licence key in <code>server.cfg</code>.</li><li>Start the server with txAdmin and log in.</li></ol><p>Need help? Open a support ticket from your account and we will help you get it running.</p>', 599.00, '299.00', 'server_pack', 'PUBLISHED', 1, '1.0.0', 'https://youtu.be/tu1KAPDJlwM', '["Custom loading screen and advanced character creation", "City hall, starter kit, car rental, crafting and cinema systems", "Advanced 24/7 stores, weapon stores, black market and modern banking", "Player-owned businesses: gas stations, farming (5-in-1), Bean Machine, Burgershot, CatCafe, Pearls, pizza job, Bahama Mamas, Vanilla Unicorn, Block Budz", "Jobs: advanced police, advanced EMS, electrician, gardener, garbage", "Drug system with player-owned drug labs and drug sales", "Heists: Vangelico, Fleeca, Pacific Bank, Casino and drug heist", "Robberies: 24/7 stores and Ammunation", "Advanced tuning, custom mechanic job, full tuning shop and super garage", "Advanced gang system and modern UI"]', '["QBCore"]', '["images/products/fivem-ultimate-advanced-rp-server-1.webp"]', '{"resources": 0, "resmon_idle_ms": "", "frameworks": ["QBCore"], "features": ["Custom loading screen and advanced character creation", "City hall, starter kit, car rental, crafting and cinema systems", "Advanced 24/7 stores, weapon stores, black market and modern banking", "Player-owned businesses: gas stations, farming (5-in-1), Bean Machine, Burgershot, CatCafe, Pearls, pizza job, Bahama Mamas, Vanilla Unicorn, Block Budz", "Jobs: advanced police, advanced EMS, electrician, gardener, garbage", "Drug system with player-owned drug labs and drug sales", "Heists: Vangelico, Fleeca, Pacific Bank, Casino and drug heist", "Robberies: 24/7 stores and Ammunation", "Advanced tuning, custom mechanic job, full tuning shop and super garage", "Advanced gang system and modern UI"], "lifetime_updates": true}', '2026-02-21 14:43:31', '2026-02-21 14:43:31'),
('p0000000-0000-0000-0000-000000419120', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'nopixel-4-clone-full-qbcore-rp-server', 'NoPixel 4.0 Clone – Full QBCore RP Server (Everything Included)', '<p>A complete and realistic QBCore roleplay server inspired by NoPixel 4.0, built for high performance and ready to launch today.</p><p>Perfect for serious RP communities who want a full city with jobs, gangs, housing and heists from day one.</p>', '<ol><li>Download the server files from <b>My library</b>.</li><li>Import the included SQL file into your MySQL/MariaDB database.</li><li>Put your database connection and licence key in <code>server.cfg</code>.</li><li>Start the server with txAdmin and log in.</li></ol><p>Need help? Open a support ticket from your account and we will help you get it running.</p>', 149.00, '90.00', 'server_pack', 'PUBLISHED', 0, '1.0.0', NULL, '["Optimized QBCore framework", "NoPixel 4.0 styled UI: custom HUD, inventory and phone", "200+ custom vehicles with realistic sounds", "Jobs: police, EMS, mechanic and gangs", "MLOs and maps: police station, MRPD, Vinewood, Burgershot and more", "Admin panel and anti-cheat", "Drug system, heists, housing and more roleplay mechanics"]', '["QBCore"]', '["images/products/nopixel-4-clone-full-qbcore-rp-server-1.webp"]', '{"resources": 0, "resmon_idle_ms": "", "frameworks": ["QBCore"], "features": ["Optimized QBCore framework", "NoPixel 4.0 styled UI: custom HUD, inventory and phone", "200+ custom vehicles with realistic sounds", "Jobs: police, EMS, mechanic and gangs", "MLOs and maps: police station, MRPD, Vinewood, Burgershot and more", "Admin panel and anti-cheat", "Drug system, heists, housing and more roleplay mechanics"], "lifetime_updates": true}', '2025-06-08 18:48:17', '2025-06-08 18:48:17'),
('p0000000-0000-0000-0000-000000342499', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'fivem-custom-qbus-server-special-edition', 'FiveM Custom QBUS Server – Special Edition', '<p>A fully customized and optimized QBUS FiveM server, special edition — built for smooth, bug-free gameplay with a clothing pack, vehicle pack and vehicle sound pack included.</p><p>After you buy, we support you: if you find a bug or error in our scripts, we fix it.</p>', '<ol><li>Download the server files from <b>My library</b>.</li><li>Import the included SQL file into your MySQL/MariaDB database.</li><li>Put your database connection and licence key in <code>server.cfg</code>.</li><li>Start the server with txAdmin and log in.</li></ol><p>Need help? Open a support ticket from your account and we will help you get it running.</p>', 179.00, '120.00', 'server_pack', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/h7eDM8BB-ko', '["QBUS / QBCore framework", "Polished UI experience", "Advanced features included", "Fully optimized server", "Clothing pack included", "Vehicle pack and vehicle sound pack included"]', '["QBCore"]', '["images/products/fivem-custom-qbus-server-special-edition-1.webp"]', '{"resources": 0, "resmon_idle_ms": "", "frameworks": ["QBCore"], "features": ["QBUS / QBCore framework", "Polished UI experience", "Advanced features included", "Fully optimized server", "Clothing pack included", "Vehicle pack and vehicle sound pack included"], "lifetime_updates": true}', '2024-12-08 21:33:36', '2024-12-08 21:33:36'),
('p0000000-0000-0000-0000-000000329171', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'hotbox-cafe-shop-mlo', 'Hotbox Cafe & Shop MLO', '<p>A new hotbox cafe and shop interior for your city — a ready-made location where players can run a shop and roleplay a business.</p><ul><li>Adds a new, immersive location for your players</li><li>Gives players a new source of income</li><li>Easy to install and use</li></ul>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the folder into your server’s <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> to your <code>server.cfg</code>.</li><li>Restart the server.</li></ol>', 7.00, NULL, 'standard', 'PUBLISHED', 0, '1.0.0', 'https://www.youtube.com/watch?v=yoOWUMAhk0U', '["Fully furnished cafe and shop interior", "Great spot for a player-run business", "Optimized and easy to install"]', '["Standalone"]', '["images/products/hotbox-cafe-shop-mlo-1.webp"]', NULL, '2024-11-08 20:42:29', '2024-11-08 20:42:29'),
('p0000000-0000-0000-0000-000000250552', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'fivem-non-brand-clothing-pack-male-female', 'FiveM Ready Non-Brand Clothing Pack – Male + Female', '<p>A premium 17.48 GB unbranded clothing package for both male and female characters, ready to stream on your FiveM server.</p><p>Watch the male and female previews: <a href="https://youtu.be/oK1gj1lWHzQ">video 1</a> · <a href="https://youtu.be/blraIpyMrr8">video 2</a>.</p>', '<ol><li>Download the pack from <b>My library</b> and extract it.</li><li>Copy the resource folder(s) into your <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> for each pack to your <code>server.cfg</code>.</li><li>Restart the server (clear the server cache if items do not appear).</li></ol>', 99.00, '60.00', 'standard', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/oK1gj1lWHzQ', '["Male and female clothing", "Non-brand (unbranded) items, safe for FiveM servers", "17.48 GB premium package"]', '["Standalone"]', '["images/photos/clothing.jpg"]', NULL, '2024-05-03 00:52:25', '2024-05-03 00:52:25'),
('p0000000-0000-0000-0000-000000200554', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'debadged-vehicle-pack-custom-engine-sounds', 'Debadged 500+ Vehicle Pack with Custom Engine Sounds', '<p>An optimized pack of more than 500 debadged vehicles with 159 custom engine sounds — sedans, supercars, sports cars, trucks, sports motorcycles, helicopters and airplanes, all in one pack.</p><p>Every vehicle is debadged, so your players get great-looking cars without real-life brand logos.</p>', '<ol><li>Download the pack from <b>My library</b> and extract it.</li><li>Copy the resource folder(s) into your <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> for each pack to your <code>server.cfg</code>.</li><li>Restart the server (clear the server cache if items do not appear).</li></ol>', 149.00, '99.00', 'standard', 'PUBLISHED', 1, '1.0.0', NULL, '["500+ optimized debadged vehicles", "159 custom engine sounds", "Sedans, supercars, sports cars, trucks, motorcycles, helicopters and planes", "No real-life brand logos", "All vehicles in one pack"]', '["Standalone"]', '["images/products/debadged-vehicle-pack-custom-engine-sounds-1.webp", "images/products/debadged-vehicle-pack-custom-engine-sounds-2.webp", "images/products/debadged-vehicle-pack-custom-engine-sounds-3.webp", "images/products/debadged-vehicle-pack-custom-engine-sounds-4.webp", "images/products/debadged-vehicle-pack-custom-engine-sounds-5.webp", "images/products/debadged-vehicle-pack-custom-engine-sounds-6.webp", "images/products/debadged-vehicle-pack-custom-engine-sounds-7.webp", "images/products/debadged-vehicle-pack-custom-engine-sounds-8.webp"]', NULL, '2024-01-03 00:00:26', '2024-01-03 00:00:26'),
('p0000000-0000-0000-0000-000000197194', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'mansion-2024-mlo', 'Mansion 2024 MLO', '<p>A modern luxury mansion with a fully furnished interior: open lounges, kitchen and dining room, bedrooms, game room, pool and terraces with city views.</p><p>Perfect for gang headquarters, rich roleplay characters or a player housing showcase.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the folder into your server’s <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> to your <code>server.cfg</code>.</li><li>Restart the server.</li></ol>', 39.00, '25.00', 'standard', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/Wu5m2l_mufA', '["Large modern mansion with full interior", "Pool, terraces and city views", "Lounges, kitchen, dining room, bedrooms and game room", "Optimized for FiveM"]', '["Standalone"]', '["images/products/mansion-2024-mlo-1.webp", "images/products/mansion-2024-mlo-2.webp", "images/products/mansion-2024-mlo-3.webp", "images/products/mansion-2024-mlo-4.webp", "images/products/mansion-2024-mlo-5.webp", "images/products/mansion-2024-mlo-6.webp", "images/products/mansion-2024-mlo-7.webp", "images/products/mansion-2024-mlo-8.webp", "images/products/mansion-2024-mlo-9.webp", "images/products/mansion-2024-mlo-10.webp", "images/products/mansion-2024-mlo-11.webp"]', NULL, '2023-12-25 18:27:36', '2023-12-25 18:27:36'),
('p0000000-0000-0000-0000-000000194453', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'richman-hospital-mlo', 'The Richman Hospital MLO (Updated)', '<p>A complete hospital interior in Richman — reception, wards and treatment rooms for your EMS team. Updated version.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the folder into your server’s <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> to your <code>server.cfg</code>.</li><li>Restart the server.</li></ol>', 49.00, '35.00', 'standard', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/bWTkLXqGMG0', '["Full hospital interior in Richman", "Reception, wards and treatment rooms", "Updated version", "Ideal for EMS roleplay"]', '["Standalone"]', '["images/products/richman-hospital-mlo-1.webp"]', NULL, '2023-12-18 23:32:19', '2023-12-18 23:32:19'),
('p0000000-0000-0000-0000-000000193811', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'clean-manor-mansion-mlo', 'Clean Manor Mansion MLO (NoPixel 4.0 Updated)', '<p>A large, elegant manor mansion for your city, updated in the NoPixel 4.0 style. A great base for families, gangs or wealthy characters.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the folder into your server’s <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> to your <code>server.cfg</code>.</li><li>Restart the server.</li></ol>', 49.00, '35.00', 'standard', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/fjuBNsir_n0', '["Large manor mansion with interior", "Updated version", "Optimized for FiveM"]', '["Standalone"]', '["images/products/clean-manor-mansion-mlo-1.webp"]', NULL, '2023-12-17 15:28:29', '2023-12-17 15:28:29'),
('p0000000-0000-0000-0000-000000186135', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'flower-police-station-mlo', 'Flower Police Station MLO', '<p>A modern police station with a distinctive flower-shaped canopy, secure entrance and parking — a fresh home for your police department.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the folder into your server’s <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> to your <code>server.cfg</code>.</li><li>Restart the server.</li></ol>', 29.00, '20.00', 'standard', 'PUBLISHED', 0, '1.0.0', NULL, '["Modern police station exterior and interior", "Secure entrance and parking", "Ideal for police roleplay"]', '["Standalone"]', '["images/products/flower-police-station-mlo-1.webp", "images/products/flower-police-station-mlo-2.webp"]', NULL, '2023-11-22 20:44:15', '2023-11-22 20:44:15'),
('p0000000-0000-0000-0000-000000178517', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'halloween-weather-pack', 'Halloween Weather Pack', '<p>Turn your city into a Halloween night: a spooky weather and sky pack, perfect for seasonal events.</p>', '<ol><li>Download the pack from <b>My library</b> and extract it.</li><li>Copy the resource folder(s) into your <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> for each pack to your <code>server.cfg</code>.</li><li>Restart the server (clear the server cache if items do not appear).</li></ol>', 5.00, NULL, 'standard', 'PUBLISHED', 0, '1.0.0', NULL, '["Spooky Halloween sky and weather", "Easy to switch on for events", "Lightweight"]', '["Standalone"]', '["images/products/halloween-weather-pack-1.webp"]', NULL, '2023-10-27 20:32:53', '2023-10-27 20:32:53'),
('p0000000-0000-0000-0000-000000175066', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'tony-stark-mansion-3-iron-man-house', 'Tony Stark Mansion 3.0 – Iron Man House', '<p>A movie-accurate cliffside mansion as a fully optimized FiveM ymap/MLO.</p><p>Special thanks: Dekurwinator, meimeiriver, Raymax, Rechkunov.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the folder into your server’s <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> to your <code>server.cfg</code>.</li><li>Restart the server.</li></ol>', 59.00, '40.00', 'standard', 'DRAFT', 0, '1.0.0', 'https://www.youtube.com/watch?v=grtTSwbsx5c', '["Full MLO with true mirrors", "Talking house A.I. HUD", "Preloaded garage with working elevator pad", "Working TVs and radios", "Full LODs, mini-maps and terrain texture blends", "Tennis court, swimmable pools, terrace and balcony"]', '["Standalone"]', '["images/products/tony-stark-mansion-3-iron-man-house-1.webp", "images/products/tony-stark-mansion-3-iron-man-house-2.webp", "images/products/tony-stark-mansion-3-iron-man-house-3.webp", "images/products/tony-stark-mansion-3-iron-man-house-4.webp", "images/products/tony-stark-mansion-3-iron-man-house-5.webp", "images/products/tony-stark-mansion-3-iron-man-house-6.webp", "images/products/tony-stark-mansion-3-iron-man-house-7.webp"]', NULL, '2023-10-14 12:50:32', NULL),
('p0000000-0000-0000-0000-000000173128', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'fivem-colored-minimap', 'FiveM Colored Minimap', '<p>A clean, colored minimap and pause-map for your server — classic look, new design and highly optimized.</p>', '<ol><li>Download the pack from <b>My library</b> and extract it.</li><li>Copy the resource folder(s) into your <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> for each pack to your <code>server.cfg</code>.</li><li>Restart the server (clear the server cache if items do not appear).</li></ol>', 10.00, NULL, 'standard', 'PUBLISHED', 0, '1.0.0', NULL, '["Clean UI", "Classic look", "Highly optimized", "New design"]', '["Standalone"]', '["images/products/fivem-colored-minimap-1.webp", "images/products/fivem-colored-minimap-2.webp", "images/products/fivem-colored-minimap-3.webp", "images/products/fivem-colored-minimap-4.webp"]', NULL, '2023-10-06 02:07:42', '2023-10-06 02:07:42'),
('p0000000-0000-0000-0000-000000166943', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'french-villa-mlo', 'French Villa MLO', '<p>A hillside French-style villa with a pool and full interior, ready for FiveM.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the folder into your server’s <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> to your <code>server.cfg</code>.</li><li>Restart the server.</li></ol>', 49.00, '36.00', 'standard', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/Cj2XZTSwbVI', '["Hillside villa with pool", "Full interior", "Ready for FiveM"]', '["Standalone"]', '["images/products/french-villa-mlo-1.webp"]', NULL, '2023-09-12 18:54:22', '2023-09-12 18:54:22'),
('p0000000-0000-0000-0000-000000149872', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'fivem-server-developer', 'FiveM Server Developer (Custom Work)', '<p>Custom development work for QBUS / QBCore servers: optimization, bug fixing and adding scripts, maps and clothing.</p>', NULL, 300.00, NULL, 'standard', 'DRAFT', 0, '1.0.0', NULL, '["Server and script optimization", "Adding or removing scripts, maps and clothes", "Bug fixing for QBUS / QBCore"]', '["QBCore"]', '["images/products/fivem-server-developer-1.webp"]', NULL, '2023-07-10 15:36:43', NULL),
('p0000000-0000-0000-0000-000000143907', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'fivem-premium-clothing-pack', 'FiveM Premium Clothing Pack', '<p>A large custom clothing pack for male and female characters for FiveM roleplay servers.</p>', '<ol><li>Download the pack from <b>My library</b> and extract it.</li><li>Copy the resource folder(s) into your <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> for each pack to your <code>server.cfg</code>.</li><li>Restart the server (clear the server cache if items do not appear).</li></ol>', 39.00, '25.00', 'standard', 'DRAFT', 0, '1.0.0', 'https://youtu.be/RF90k5S7tTY', '["Male: 158 hairstyles, 237 masks, 243 shirts, 525 jackets, 193 pants, 147 shoes and more", "Female: 193 hairstyles, 222 masks, 343 shirts, 550 jackets, 211 pants, 157 shoes and more", "Bags, armor, hats, glasses, earrings, watches and bracelets for both"]', '["Standalone"]', '["images/products/fivem-premium-clothing-pack-1.webp", "images/products/fivem-premium-clothing-pack-2.webp", "images/products/fivem-premium-clothing-pack-3.webp", "images/products/fivem-premium-clothing-pack-4.webp", "images/products/fivem-premium-clothing-pack-5.webp", "images/products/fivem-premium-clothing-pack-6.webp"]', NULL, '2023-06-15 12:17:09', NULL),
('p0000000-0000-0000-0000-000000134705', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'custom-qbus-server-monthly-updates', 'Custom QBUS Server with Monthly Updates (NoPixel 4.0 Inspired)', '<p>A fully customized QBUS FiveM server inspired by NoPixel 4.0, built for top performance — with monthly updates, a 500+ debadged car pack and a premium clothing pack included.</p><p>Previews: <a href="https://youtu.be/M9eyzLJu4zs">the server</a> · <a href="https://youtu.be/RF90k5S7tTY">clothing pack</a> · <a href="https://youtu.be/WfGjZiGa14o">car pack</a>.</p><p>After you buy, we support you: if you find a bug in our scripts, we fix it within 48 hours.</p>', '<ol><li>Download the server files from <b>My library</b>.</li><li>Import the included SQL file into your MySQL/MariaDB database.</li><li>Put your database connection and licence key in <code>server.cfg</code>.</li><li>Start the server with txAdmin and log in.</li></ol><p>Need help? Open a support ticket from your account and we will help you get it running.</p>', 249.00, '180.00', 'server_pack', 'PUBLISHED', 1, '1.0.0', 'https://youtu.be/0qdteAaC0ak', '["Fully custom, optimized QBUS FiveM server", "Monthly updates with new scripts", "500+ debadged cars included", "Premium clothing pack included", "Installation help included", "Bug fixes within 48 hours"]', '["QBCore"]', '["images/products/custom-qbus-server-monthly-updates-1.webp"]', '{"resources": 0, "resmon_idle_ms": "", "frameworks": ["QBCore"], "features": ["Fully custom, optimized QBUS FiveM server", "Monthly updates with new scripts", "500+ debadged cars included", "Premium clothing pack included", "Installation help included", "Bug fixes within 48 hours"], "lifetime_updates": true}', '2023-05-05 20:27:20', '2023-05-05 20:27:20'),
('p0000000-0000-0000-0000-000000129785', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'qbcore-esx-smartphone-open-source', '[QBCore/ESX] SmartPhone – Open Source (iPhone 14 Inspired)', '<p>A modern smartphone for QBCore and ESX servers, fully open source with no lock, so you can customize everything.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the resource into your <code>resources</code> folder and import any included SQL file.</li><li>Add <code>ensure &lt;resource name&gt;</code> to your <code>server.cfg</code> after your framework.</li><li>Restart the server and adjust <code>config.lua</code> to taste.</li></ol>', 69.00, '45.00', 'standard', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/ugBJVPlg8Bo', '["Latest smartphone design", "Works with QBCore and ESX", "Fully open source — no lock"]', '["QBCore", "ESX"]', '["images/products/qbcore-esx-smartphone-open-source-1.webp"]', NULL, '2023-04-13 01:17:45', '2023-04-13 01:17:45'),
('p0000000-0000-0000-0000-000000129783', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'qbcore-phone-13-pro-max-open-source', 'QBCore Phone (iPhone 13 Pro Max Style) – Open Source', '<p>A completely redesigned QBCore phone in an iOS 16 style, fully open source. Uses the latest <code>exports[''qb-core'']:GetCoreObject()</code>.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the resource into your <code>resources</code> folder and import any included SQL file.</li><li>Add <code>ensure &lt;resource name&gt;</code> to your <code>server.cfg</code> after your framework.</li><li>Restart the server and adjust <code>config.lua</code> to taste.</li></ol>', 49.00, '35.00', 'standard', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/wwvi6JCnaEA', '["iOS 16 style design", "Garage app with vehicle details and damage warnings", "Banking app with transfers (IBAN, ID or contact)", "Racing app, App Store with sound effects", "MDT app for citizens, vehicles and properties", "Home app: keys, GPS and house transfers", "Phone, contacts, call history and WhatsApp-style messaging with groups, photos and GPS", "Compatible with pma-voice, mumble, salty-chat and tokovoip"]', '["QBCore"]', '["images/products/qbcore-phone-13-pro-max-open-source-1.webp"]', NULL, '2023-04-13 01:16:36', '2023-04-13 01:16:36'),
('p0000000-0000-0000-0000-000000129383', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'qbcore-fake-id-card-qb-forgery', 'QBCore Fake ID Card (qb-forgery)', '<p>Let criminals forge in-game ID cards on your QBCore server — a simple resource that adds depth to illegal roleplay.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the resource into your <code>resources</code> folder and import any included SQL file.</li><li>Add <code>ensure &lt;resource name&gt;</code> to your <code>server.cfg</code> after your framework.</li><li>Restart the server and adjust <code>config.lua</code> to taste.</li></ol>', 5.00, NULL, 'standard', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/E1VFvF6qFRI', '["In-game forged ID cards for criminal roleplay", "QBCore ready", "Resource name: qb-forgery"]', '["QBCore"]', '["images/products/qbcore-fake-id-card-qb-forgery-1.webp"]', NULL, '2023-04-11 00:50:49', '2023-04-11 00:50:49'),
('p0000000-0000-0000-0000-000000129382', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'cayo-perico-bridge', 'Cayo Perico Bridge', '<p>A drivable bridge connecting Los Santos to Cayo Perico — no boats or planes needed.</p>', '<ol><li>Download the pack from <b>My library</b> and extract it.</li><li>Copy the resource folder(s) into your <code>resources</code> folder.</li><li>Add <code>ensure &lt;folder name&gt;</code> for each pack to your <code>server.cfg</code>.</li><li>Restart the server (clear the server cache if items do not appear).</li></ol>', 5.00, NULL, 'standard', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/wTbdnZdHEKE', '["Drivable bridge from Los Santos to Cayo Perico", "Map addon", "Lightweight"]', '["Standalone"]', '["images/products/cayo-perico-bridge-1.webp"]', NULL, '2023-04-11 00:47:34', '2023-04-11 00:47:34'),
('p0000000-0000-0000-0000-000000129381', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'qb-vape', 'qb-vape – Vape Script', '<p>A usable vape item for QBCore with realistic smoke effects.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the resource into your <code>resources</code> folder and import any included SQL file.</li><li>Add <code>ensure &lt;resource name&gt;</code> to your <code>server.cfg</code> after your framework.</li><li>Restart the server and adjust <code>config.lua</code> to taste.</li></ol>', 5.00, NULL, 'standard', 'PUBLISHED', 0, '1.0.0', 'https://youtu.be/yZJlwcFbFE8', '["Usable vape item with smoke effects", "QBCore ready", "Lightweight"]', '["QBCore"]', '["images/products/qb-vape-1.webp"]', NULL, '2023-04-11 00:46:26', '2023-04-11 00:46:26'),
('p0000000-0000-0000-0000-000000129380', (SELECT id FROM users WHERE role = 'ADMIN' ORDER BY created_at LIMIT 1), 'qbcore-pause-menu', 'QBCore Pause Menu', '<p>A modern pause menu for QBCore showing the player’s job, cash and bank money, with mini games and quick links.</p>', '<ol><li>Download the files from <b>My library</b> and extract them.</li><li>Copy the resource into your <code>resources</code> folder and import any included SQL file.</li><li>Add <code>ensure &lt;resource name&gt;</code> to your <code>server.cfg</code> after your framework.</li><li>Restart the server and adjust <code>config.lua</code> to taste.</li></ol>', 5.00, NULL, 'standard', 'PUBLISHED', 0, '1.0.0', NULL, '["Player card with job, cash and bank balance", "Active player count", "Mini games: Hextris, Tower Building, Drill Bunny, Pacman, Pool, Tetris", "Discord, settings, map and social links"]', '["QBCore"]', '["images/products/qbcore-pause-menu-1.webp"]', NULL, '2023-04-11 00:44:53', '2023-04-11 00:44:53')
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `install_guide` = VALUES(`install_guide`),
